import sys

def can_form_symmetric_matrix(n, k):
    if k % 2 != 0:
        return -1

    # Calculate the maximum number of ones we can place on the upper triangle including the diagonal
    max_ones = (n * (n + 1)) // 2

    if k > max_ones:
        return -1

    # Initialize the matrix with zeros
    matrix = [[0] * n for _ in range(n)]

    # Place the ones in the upper triangle including the diagonal
    ones_placed = 0
    for i in range(n):
        for j in range(i, n):
            if ones_placed < k:
                matrix[i][j] = 1
                matrix[j][i] = 1
                ones_placed += 2

    return matrix

def main():
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    k = int(data[1])

    result = can_form_symmetric_matrix(n, k)

    if result == -1:
        print(-1)
    else:
        for row in result:
            print(' '.join(map(str, row)))

